107→// ReadSession reads a session from Claude's storage (JSONL transcript file).
108→// The session data is stored in NativeData as raw JSONL bytes.
109→// ModifiedFiles is computed by parsing the transcript.
110→func (c *ClaudeCodeAgent) ReadSession(input *agent.HookInput) (*agent.AgentSession, error) {
111→	if input.SessionRef == "" {
112→		return nil, errors.New("session reference (transcript path) is required")
113→	}
114→
115→	// Read the raw JSONL file
116→	data, err := os.ReadFile(input.SessionRef)
117→	if err != nil {
118→		return nil, fmt.Errorf("failed to read transcript: %w", err)
119→	}
120→
121→	// Parse to extract computed fields
122→	lines, err := transcript.ParseFromBytes(data)
123→	if err != nil {
124→		return nil, fmt.Errorf("failed to parse transcript: %w", err)
125→	}
126→
127→	return &agent.AgentSession{
128→		SessionID:     input.SessionID,
129→		AgentName:     c.Name(),
130→		SessionRef:    input.SessionRef,
131→		StartTime:     time.Now(),
132→		NativeData:    data,
133→		ModifiedFiles: ExtractModifiedFiles(lines),
134→	}, nil
135→}
136→
137→// WriteSession writes a session to Claude's storage (JSONL transcript file).
138→// Uses the NativeData field which contains raw JSONL bytes.
139→// The session must have been created by Claude Code (AgentName check).
140→func (c *ClaudeCodeAgent) WriteSession(_ context.Context, session *agent.AgentSession) error {
141→	if session == nil {
142→		return errors.New("session is nil")
143→	}
144→
145→	// Verify this session belongs to Claude Code
146→	if session.AgentName != "" && session.AgentName != c.Name() {
147→		return fmt.Errorf("session belongs to agent %q, not %q", session.AgentName, c.Name())
148→	}
149→
150→	if session.SessionRef == "" {
151→		return errors.New("session reference (transcript path) is required")
152→	}
153→
154→	if len(session.NativeData) == 0 {
155→		return errors.New("session has no native data to write")
156→	}
157→
158→	// Write the raw JSONL data
159→	if err := os.WriteFile(session.SessionRef, session.NativeData, 0o600); err != nil {
160→		return fmt.Errorf("failed to write transcript: %w", err)
161→	}
162→
163→	return nil
164→}
