247→// SanitizePathForClaude converts a path to Claude's project directory format.
248→// Claude replaces any non-alphanumeric character with a dash.
249→var nonAlphanumericRegex = regexp.MustCompile(`[^a-zA-Z0-9]`)
250→
251→func SanitizePathForClaude(path string) string {
252→	return nonAlphanumericRegex.ReplaceAllString(path, "-")
253→}
