 17→// Transcript message type constants - aliases to transcript package for local use.
 18→const (
 19→	transcriptTypeUser = transcript.TypeUser
 20→)
 21→
 22→// resolveTranscriptPath determines the correct file path for an agent's session transcript.
 23→// Computes the path dynamically from the current repo location for cross-machine portability.
 24→func resolveTranscriptPath(ctx context.Context, sessionID string, agent agentpkg.Agent) (string, error) {
 25→	repoRoot, err := paths.WorktreeRoot(ctx)
 26→	if err != nil {
 27→		return "", fmt.Errorf("failed to get worktree root: %w", err)
 28→	}
 29→
 30→	sessionDir, err := agent.GetSessionDir(repoRoot)
 31→	if err != nil {
 32→		return "", fmt.Errorf("failed to get agent session directory: %w", err)
 33→	}
 34→	return agent.ResolveSessionFile(sessionDir, sessionID), nil
 35→}
 36→
 37→// AgentTranscriptPath returns the path to a subagent's transcript file.
 38→// Subagent transcripts are stored as agent-{agentId}.jsonl in the same directory
 39→// as the main transcript.
 40→func AgentTranscriptPath(transcriptDir, agentID string) string {
 41→	return filepath.Join(transcriptDir, fmt.Sprintf("agent-%s.jsonl", agentID))
 42→}
 43→
 44→// toolResultBlock represents a tool_result in a user message
 45→type toolResultBlock struct {
 46→	Type      string `json:"type"`
 47→	ToolUseID string `json:"tool_use_id"`
 48→}
 49→
 50→// userMessageWithToolResults represents a user message that may contain tool results
 51→type userMessageWithToolResults struct {
 52→	Content []toolResultBlock `json:"content"`
 53→}
 54→
 55→// FindCheckpointUUID finds the UUID of the message containing the tool_result
 56→// for the given tool_use_id. This is used to find the checkpoint point for
 57→// transcript truncation when rewinding to a task.
 58→// Returns the UUID and true if found, empty string and false otherwise.
 59→func FindCheckpointUUID(transcript []transcriptLine, toolUseID string) (string, bool) {
 60→	for _, line := range transcript {
 61→		if line.Type != transcriptTypeUser {
 62→			continue
 63→		}
 64→
 65→		var msg userMessageWithToolResults
 66→		if err := json.Unmarshal(line.Message, &msg); err != nil {
 67→			continue
 68→		}
 69→
 70→		for _, block := range msg.Content {
 71→			if block.Type == "tool_result" && block.ToolUseID == toolUseID {
 72→				return line.UUID, true
 73→			}
 74→		}
 75→	}
 76→	return "", false
 77→}
 78→
 79→// TruncateTranscriptAtUUID returns transcript lines up to and including the
 80→// line with the given UUID. If the UUID is not found or is empty, returns
 81→// the entire transcript.
 82→//
 83→//nolint:revive // Exported for testing purposes
 84→func TruncateTranscriptAtUUID(transcript []transcriptLine, uuid string) []transcriptLine {
 85→	if uuid == "" {
 86→		return transcript
 87→	}
 88→
 89→	for i, line := range transcript {
 90→		if line.UUID == uuid {
 91→			return transcript[:i+1]
 92→		}
 93→	}
 94→
 95→	// UUID not found, return full transcript
 96→	return transcript
 97→}
 98→
 99→// writeTranscript writes transcript lines to a file in JSONL format.
100→func writeTranscript(path string, transcript []transcriptLine) error {
101→	file, err := os.Create(path) //nolint:gosec // Writing to controlled git metadata path
102→	if err != nil {
103→		return fmt.Errorf("failed to create file: %w", err)
104→	}
105→	defer func() { _ = file.Close() }()
106→
107→	for _, line := range transcript {
108→		data, err := json.Marshal(line)
109→		if err != nil {
110→			return fmt.Errorf("failed to marshal line: %w", err)
111→		}
112→		if _, err := file.Write(data); err != nil {
113→			return fmt.Errorf("failed to write line: %w", err)
114→		}
115→		if _, err := file.WriteString("\n"); err != nil {
116→			return fmt.Errorf("failed to write newline: %w", err)
117→		}
118→	}
119→
120→	return nil
121→}
122→
123→// TranscriptPosition contains the position information for a transcript file.
124→type TranscriptPosition struct {
125→	LastUUID  string // Last non-empty UUID (from user/assistant messages)
126→	LineCount int    // Total number of lines
127→}
128→
129→// GetTranscriptPosition reads a transcript file and returns the last UUID and line count.
130→// Returns empty position if file doesn't exist or is empty.
131→// Only considers UUIDs from actual messages (user/assistant), not summary rows which use leafUuid.
132→func GetTranscriptPosition(path string) (TranscriptPosition, error) {
133→	if path == "" {
134→		return TranscriptPosition{}, nil
135→	}
136→
137→	file, err := os.Open(path) //nolint:gosec // Reading from controlled transcript path
138→	if err != nil {
139→		if os.IsNotExist(err) {
140→			return TranscriptPosition{}, nil
141→		}
142→		return TranscriptPosition{}, fmt.Errorf("failed to open transcript: %w", err)
143→	}
144→	defer func() { _ = file.Close() }()
145→
146→	var pos TranscriptPosition
147→	reader := bufio.NewReader(file)
148→
149→	for {
150→		lineBytes, err := reader.ReadBytes('\n')
151→		if err != nil && err != io.EOF {
152→			return TranscriptPosition{}, fmt.Errorf("failed to read transcript: %w", err)
153→		}
154→
155→		if len(lineBytes) == 0 {
156→			if err == io.EOF {
157→				break
158→			}
159→			continue
160→		}
161→
162→		pos.LineCount++
163→
164→		// Parse line to extract UUID (only from user/assistant messages, not summaries)
165→		var line transcriptLine
166→		if err := json.Unmarshal(lineBytes, &line); err == nil {
167→			if line.UUID != "" {
168→				pos.LastUUID = line.UUID
169→			}
170→		}
171→
172→		if err == io.EOF {
173→			break
174→		}
175→	}
176→
177→	return pos, nil
178→}
