package claudecode

import (
	"context"
	"os"
	"os/exec"
	"path/filepath"
	"testing"

	"github.com/entireio/cli/cmd/entire/cli/paths"
	"github.com/entireio/cli/cmd/entire/cli/testutil"
)

// TestGetSessionDir_ClaudeWorktree verifies that GetSessionDir returns the
// correct project directory when running from a Claude Code worktree
// (created under .claude/worktrees/).
//
// Bug: When Claude Code uses --worktree, it creates a git worktree under
// .claude/worktrees/<branch>/. Entire's hooks run from within that worktree,
// so paths.WorktreeRoot() returns the worktree path (e.g.,
// /repo/.claude/worktrees/feature-branch) instead of the main repo path (/repo).
//
// GetSessionDir sanitizes this path to derive Claude's project directory,
// producing a path like ~/.claude/projects/-repo--claude-worktrees-feature-branch
// instead of the correct ~/.claude/projects/-repo.
//
// This causes resolveTranscriptPath (used during rewind and resume) to look
// in the wrong directory and fail to find transcript files.
func TestGetSessionDir_ClaudeWorktree(t *testing.T) {
	t.Parallel()

	// Set up a git repo with an initial commit
	mainRepo := t.TempDir()
	testutil.InitRepo(t, mainRepo)
	testutil.WriteFile(t, mainRepo, "README.md", "# Test")
	testutil.GitAdd(t, mainRepo, "README.md")
	testutil.GitCommit(t, mainRepo, "initial commit")

	// Create a Claude worktree under .claude/worktrees/ (mimicking Claude Code --worktree)
	worktreeBranch := "feature-branch"
	worktreeDir := filepath.Join(mainRepo, ".claude", "worktrees", worktreeBranch)
	if err := os.MkdirAll(filepath.Dir(worktreeDir), 0o755); err != nil {
		t.Fatalf("failed to create .claude/worktrees dir: %v", err)
	}

	cmd := exec.Command("git", "worktree", "add", worktreeDir, "-b", worktreeBranch) //nolint:gosec // test code
	cmd.Dir = mainRepo
	cmd.Env = testutil.GitIsolatedEnv()
	if output, err := cmd.CombinedOutput(); err != nil {
		t.Fatalf("failed to create worktree: %v\nOutput: %s", err, output)
	}

	// Override home dir to make GetSessionDir deterministic
	origHome := os.Getenv("HOME")
	fakeHome := t.TempDir()
	t.Setenv("HOME", fakeHome)
	_ = origHome

	agent := &ClaudeCodeAgent{}

	// GetSessionDir from main repo path
	mainSessionDir, err := agent.GetSessionDir(mainRepo)
	if err != nil {
		t.Fatalf("GetSessionDir(mainRepo) error: %v", err)
	}

	// GetSessionDir from worktree path (what Entire actually uses via WorktreeRoot)
	worktreeSessionDir, err := agent.GetSessionDir(worktreeDir)
	if err != nil {
		t.Fatalf("GetSessionDir(worktreeDir) error: %v", err)
	}

	// BUG: These produce different paths because the worktree path includes
	// .claude/worktrees/<branch> which gets sanitized differently.
	// mainSessionDir:    ~/.claude/projects/-tmp-xxx-repo
	// worktreeSessionDir: ~/.claude/projects/-tmp-xxx-repo--claude-worktrees-feature-branch
	if mainSessionDir == worktreeSessionDir {
		// This is what we WANT (correct behavior), but currently they differ
		t.Log("GetSessionDir correctly resolves to same path for main repo and worktree (fixed)")
	} else {
		t.Errorf("GetSessionDir path mismatch for Claude worktree:\n"+
			"  main repo:  %s\n"+
			"  worktree:   %s\n"+
			"  These should be identical but differ because the worktree path\n"+
			"  (.claude/worktrees/<branch>) is sanitized differently than the main repo path.\n"+
			"  This causes rewind/resume to look for transcripts in the wrong directory.",
			mainSessionDir, worktreeSessionDir)
	}
}

// TestResolveTranscriptPath_ClaudeWorktree verifies that transcript path
// resolution works correctly when running from a Claude Code worktree.
//
// This is the end-to-end scenario: Claude provides a transcript_path in hook
// input (stored in session state), but during rewind/resume, the CLI
// re-derives the path using WorktreeRoot() + GetSessionDir(). When running
// from a worktree under .claude/worktrees/, the re-derived path is wrong.
func TestResolveTranscriptPath_ClaudeWorktree(t *testing.T) {
	t.Parallel()

	// Set up a git repo
	mainRepo := t.TempDir()
	testutil.InitRepo(t, mainRepo)
	testutil.WriteFile(t, mainRepo, "README.md", "# Test")
	testutil.GitAdd(t, mainRepo, "README.md")
	testutil.GitCommit(t, mainRepo, "initial commit")

	// Create worktree under .claude/worktrees/
	worktreeBranch := "wt-branch"
	worktreeDir := filepath.Join(mainRepo, ".claude", "worktrees", worktreeBranch)
	if err := os.MkdirAll(filepath.Dir(worktreeDir), 0o755); err != nil {
		t.Fatalf("failed to create .claude/worktrees dir: %v", err)
	}

	cmd := exec.Command("git", "worktree", "add", worktreeDir, "-b", worktreeBranch) //nolint:gosec // test code
	cmd.Dir = mainRepo
	cmd.Env = testutil.GitIsolatedEnv()
	if output, err := cmd.CombinedOutput(); err != nil {
		t.Fatalf("failed to create worktree: %v\nOutput: %s", err, output)
	}

	// Override home dir
	fakeHome := t.TempDir()
	t.Setenv("HOME", fakeHome)

	agent := &ClaudeCodeAgent{}

	// Simulate Claude storing a transcript under the main repo's project dir
	mainSessionDir, _ := agent.GetSessionDir(mainRepo)
	if err := os.MkdirAll(mainSessionDir, 0o755); err != nil {
		t.Fatalf("failed to create session dir: %v", err)
	}
	sessionID := "test-session-abc"
	transcriptPath := agent.ResolveSessionFile(mainSessionDir, sessionID)
	if err := os.WriteFile(transcriptPath, []byte(`{"type":"user","message":"hello"}`+"\n"), 0o600); err != nil {
		t.Fatalf("failed to write transcript: %v", err)
	}

	// Now simulate what happens during rewind/resume:
	// WorktreeRoot() returns the worktree path, and we re-derive the session dir
	paths.ClearWorktreeRootCache()

	// Change to worktree directory (simulating hooks running from Claude worktree)
	// Note: t.Chdir and t.Parallel don't mix, but we need this for WorktreeRoot()
	// to return the worktree path. Instead, compute what WorktreeRoot would return.
	ctx := context.Background()
	_ = ctx

	// Directly verify the path mismatch
	worktreeSessionDir, _ := agent.GetSessionDir(worktreeDir)
	reDerivedPath := agent.ResolveSessionFile(worktreeSessionDir, sessionID)

	// The transcript exists at the main-repo-derived path
	if _, err := os.Stat(transcriptPath); err != nil {
		t.Fatalf("transcript should exist at main repo path %s: %v", transcriptPath, err)
	}

	// But the re-derived path (from worktree) is different and doesn't exist
	if transcriptPath == reDerivedPath {
		t.Log("Transcript paths match (fixed)")
	} else {
		if _, err := os.Stat(reDerivedPath); err == nil {
			t.Error("re-derived path unexpectedly exists")
		}
		t.Errorf("Transcript path mismatch when resolving from Claude worktree:\n"+
			"  actual (from hook input): %s (exists)\n"+
			"  re-derived (from worktree): %s (does not exist)\n"+
			"  During rewind/resume, the CLI re-derives the path using WorktreeRoot()\n"+
			"  which returns the worktree path instead of the main repo path.",
			transcriptPath, reDerivedPath)
	}
}

