	t.Setenv("ENTIRE_TEST_CLAUDE_PROJECT_DIR", "") // Ensure no test override

	ag := &ClaudeCodeAgent{}

	// GetSessionDir from main repo path (what Claude uses for its project dir)
	mainSessionDir, err := ag.GetSessionDir(mainRepo)
	if err != nil {
		t.Fatalf("GetSessionDir(mainRepo) error: %v", err)
	}

	// GetSessionDir from worktree path (what a naive WorktreeRoot call would produce)
	worktreeSessionDir, err := ag.GetSessionDir(worktreeDir)
	if err != nil {
		t.Fatalf("GetSessionDir(worktreeDir) error: %v", err)
