121→// IsLinkedWorktree returns true if the given path is inside a linked git worktree
122→// (as opposed to the main repository). Linked worktrees have .git as a file
123→// pointing to the main repo, while the main repo has .git as a directory.
124→func IsLinkedWorktree(worktreeRoot string) bool {
125→	gitPath := filepath.Join(worktreeRoot, ".git")
126→	info, err := os.Stat(gitPath)
127→	if err != nil {
128→		return false
129→	}
130→	return !info.IsDir()
131→}
